import numpy as np
rows=np.load('/tmp/rows.npy'); KL,LP,LEN,P=rows.T; D=np.sqrt(KL); L0=280.15
a,b=303.708,0.98
Dt=a*D/(1+b*LP)
keys=sorted(set(KL)); G=np.array([keys.index(k) for k in KL])
best=None
for s in np.linspace(80,140,601):
    X=np.column_stack([G==i for i in range(len(keys))]+[np.tanh(Dt/s)])
    coef,_,_,_=np.linalg.lstsq(X,P,rcond=None); r=P-X@coef; ss=(r**2).sum()
    if best is None or ss<best[0]: best=(ss,s,coef,r)
ss,s,coef,r=best
print('s',s,'A',coef[-1]); 
for k,q in zip(keys,coef[:-1]): print('KL %.4f d %.3f Q %.4f'%(k,np.sqrt(k),q))
print('resid by lp:')
for l in sorted(set(LP)): print(l, round(r[LP==l].mean(),4), round(r[LP==l].std(),4), (LP==l).sum())
# free-power tanh: tanh((D/s)^k)
best=None
for k in np.linspace(0.7,1.5,33):
  for s in np.linspace(60,180,121):
    X=np.column_stack([G==i for i in range(len(keys))]+[np.tanh((Dt/s)**k)])
    coef,_,_,_=np.linalg.lstsq(X,P,rcond=None); r=P-X@coef; ss2=(r**2).sum()
    if best is None or ss2<best[0]: best=(ss2,k,s,coef[-1],coef[-2])
print('tanh power',best)
ss2,k,s2,A,Q0=best; lt=A*np.tanh((a*np.sqrt(2.737963)/s2)**k); print('frac',lt/(Q0+lt))
